#include "speech.h"
#include "announcement.h"
#include <QCoreApplication>
#include <QDir>
#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonArray>
#include <QtEndian>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc<2)return 2;try{QString root=QString::fromLocal8Bit(argv[1]);if(!QDir().mkpath(root))return 2;SpeechSettings settings;settings.enabled=true;settings.volume=80;QString voiceName;for(auto voice:SpeechService::voices())if(voice.french){settings.voice=voice.id;voiceName=voice.name;break;}if(settings.voice.isEmpty())throw std::runtime_error("Aucune voix française SAPI installée");auto backend=makeWindowsSpeechBackend();backend->configure(settings);std::atomic_bool cancel=false;QJsonArray cases;
 QList<QPair<QString,QString>> examples;for(auto code:QStringList{"P002","P004","P017","P026","P039","P069"})examples.append(QPair<QString,QString>{code,"APPEL: 50263090555 MED, "+code+" - AGRESSION - BAGARRE, N5 0"});
 examples.append(QPair<QString,QString>{"nombres","12 victimes, 25 ans, 125 mètres, 39 personnes. Rendez-vous à 18h30 au 12 rue Jean-Jaurès. Téléphone : 0471 12 34 56. Référence 0007. SMUR et CHU."});
 examples.append(QPair<QString,QString>{"long","APPEL: 123 MED, P039 - Intervention à 18h30, 12 rue Jean-Jaurès. Il y a 12 victimes et 39 personnes présentes. La victime a 25 ans. Le point de rendez-vous est à 125 mètres. Attendre le SMUR, puis transmettre le bilan complet. Fin du message de contrôle."});
 for(auto example:examples){auto spoken=preparedAnnouncement("départ ambulance R-MED1",example.second);auto path=QDir(root).filePath(example.first+".wav");backend->configure(settings);backend->synthesize(spoken,path,cancel);QFile file(path);if(!file.open(QIODevice::ReadOnly))throw std::runtime_error("WAV absent");auto bytes=file.readAll();int data=-1;quint32 size=0;for(int pos=12;pos+8<=bytes.size();){auto n=qFromLittleEndian<quint32>(bytes.constData()+pos+4);if(bytes.mid(pos,4)=="data"){data=pos+8;size=n;break;}pos+=8+n+(n&1);}if(data<0||size<44100||data+size>quint32(bytes.size()))throw std::runtime_error("WAV incomplet");qint64 energy=0;int longestSilence=0,silence=0;for(quint32 i=0;i+1<size;i+=2){int v=qFromLittleEndian<qint16>(bytes.constData()+data+i);energy+=qAbs(v);if(qAbs(v)<100){++silence;longestSilence=qMax(longestSilence,silence);}else silence=0;}if(!energy)throw std::runtime_error("WAV silencieux");cases.append(QJsonObject{{"name",example.first},{"original",example.second},{"utterance",spoken},{"seconds",double(size)/44100},{"mean_absolute_pcm",double(energy)/(size/2)},{"longest_low_level_seconds",double(longestSilence)/22050},{"wav_valid",true}});if(app.arguments().contains("--play")&&example.first=="P039"){backend->configure(settings);backend->speak(spoken,cancel);}}
 QFile report(QDir(root).filePath("sapi-report.json"));if(!report.open(QIODevice::WriteOnly))return 2;report.write(QJsonDocument(QJsonObject{{"voice",voiceName},{"french_selected",true},{"human_listening","pending; WAV signal checks do not prove intelligibility"},{"cases",cases}}).toJson());std::cout<<"PASS real French SAPI: 8 complete non-silent PCM WAV files\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
